cat > server/repositories/issue-import-repository.ts <<'EOF'
/**
 * Bulk issue import: the persisted import keys and the single-transaction write of a whole batch.
 */
import { and, eq, isNull, max } from "drizzle-orm";
import { newId } from "@/lib/id";
import {
  getDb,
  issueImports,
  issueLabels,
  issues,
  labels,
  members,
  users,
} from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toIssue } from "./_mappers";
import type { ImportIssueRowInput } from "@/schemas/issue-import";
import type { IssueId, LabelId, OrgId, ProjectId, UserId } from "@/types/common";
import type { Issue } from "@/types/issue";

const DEFAULT_LABEL_COLOR = "#94a3b8";

/** Issue ids of an earlier import with this key, in file order; null if none. */
export async function findImportedIssueIds(
  orgId: OrgId,
  importKey: string,
): Promise<readonly IssueId[] | null> {
  const row = getDb()
    .select()
    .from(issueImports)
    .where(
      and(eq(issueImports.orgId, orgId), eq(issueImports.importKey, importKey)),
    )
    .get();
  return row ? (JSON.parse(row.issueIds) as IssueId[]) : null;
}

/** Lower-cased email → user id for the workspace's current active members. */
export async function activeMemberIdsByEmail(
  orgId: OrgId,
): Promise<ReadonlyMap<string, UserId>> {
  const rows = getDb()
    .select({ userId: users.id, email: users.email })
    .from(members)
    .innerJoin(users, eq(users.id, members.userId))
    .where(
      and(
        eq(members.orgId, orgId),
        eq(members.status, "active"),
        isNull(members.archivedAt),
      ),
    )
    .all();
  return new Map(rows.map((r) => [r.email.toLowerCase(), r.userId as UserId]));
}

/** Writes labels, issues, label joins and the import key atomically. */
export function writeImport(
  orgId: OrgId,
  projectId: ProjectId,
  importKey: string,
  authorId: UserId,
  rows: readonly ImportIssueRowInput[],
  assignees: ReadonlyMap<string, UserId>,
): readonly Issue[] {
  return getDb().transaction((tx) => {
    const stamp = toIsoTimestamp(new Date());

    const labelIds = new Map<string, LabelId>(
      tx
        .select()
        .from(labels)
        .where(eq(labels.orgId, orgId))
        .all()
        .map((l) => [l.name, l.id as LabelId]),
    );
    for (const row of rows) {
      for (const name of row.labels) {
        if (labelIds.has(name)) continue;
        const created = tx
          .insert(labels)
          .values({
            id: newId(),
            orgId,
            name,
            color: DEFAULT_LABEL_COLOR,
            description: null,
            createdAt: stamp,
            updatedAt: stamp,
          })
          .returning()
          .get();
        labelIds.set(name, created.id as LabelId);
      }
    }

    let next =
      (tx
        .select({ value: max(issues.number) })
        .from(issues)
        .where(and(eq(issues.orgId, orgId), eq(issues.projectId, projectId)))
        .get()?.value ?? 0) + 1;

    const created: Issue[] = [];
    for (const row of rows) {
      const assigneeId =
        row.assigneeEmail === null
          ? null
          : (assignees.get(row.assigneeEmail.toLowerCase()) ?? null);
      const issueRow = tx
        .insert(issues)
        .values({
          id: newId(),
          orgId,
          projectId,
          number: next++,
          title: row.title,
          description: row.description,
          status: row.status,
          priority: row.priority,
          authorId,
          assigneeId,
          parentId: null,
          estimate: null,
          dueAt: row.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .returning()
        .get();

      const ids = [
        ...new Set(row.labels.map((name) => labelIds.get(name) as LabelId)),
      ];
      if (ids.length > 0) {
        tx.insert(issueLabels)
          .values(ids.map((labelId) => ({ orgId, issueId: issueRow.id, labelId })))
          .run();
      }
      created.push(toIssue(issueRow, ids));
    }

    tx.insert(issueImports)
      .values({
        id: newId(),
        orgId,
        importKey,
        projectId,
        issueIds: JSON.stringify(created.map((i) => i.id)),
        createdAt: stamp,
      })
      .run();

    return created;
  });
}
