 * Bulk import: every row becomes an issue, or none does. Gated like a create,
 * replay-safe per workspace via `importKey`, announced with one batch event.
 */
export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const previous = await importRepo.findImportedIssueIds(
    input.orgId,
    input.importKey,
  );
  if (previous !== null) {
    const found = await Promise.all(
      previous.map((id) => issueRepo.findIssueById(input.orgId, id)),
    );
    return {
      importKey: input.importKey,
      projectId: input.projectId,
      issues: found.filter((issue): issue is Issue => issue !== null),
      replayed: true,
    };
  }

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used, input.rows.length)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  const verdict = await consumeRateLimit(
    input.orgId,
    "issue:create",
    input.rows.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Issue creation rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const assignees = await importRepo.activeMemberIdsByEmail(input.orgId);
  const created = importRepo.writeImport(
    input.orgId,
    input.projectId,
    input.importKey,
    actor.userId,
    input.rows,
    assignees,
  );

  await emit("issues.imported", {
    ...actorEnvelope(actor),
    projectId: input.projectId,
    importKey: input.importKey,
    issueIds: created.map((issue) => issue.id),
  });

  return {
    importKey: input.importKey,
    projectId: input.projectId,
    issues: created,
    replayed: false,
  };
}

